package com.temery.hunterscompanion;
import android.net.Uri;import android.provider.DocumentsContract;import android.database.Cursor;import android.graphics.BitmapFactory;import java.io.InputStream;
import android.app.*;import android.os.*;import android.content.*;import android.hardware.display.*;import android.view.*;import android.widget.*;import android.graphics.Color;import android.graphics.Typeface;

public class MainActivity extends Activity {
 ImageView background; TextView folderStatus; android.content.SharedPreferences prefs;
 LinearLayout panel; TextView body; View shade; boolean art=false; int ink=0xffe5ddcd; int gold=0xffb59b71;
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("setup",MODE_PRIVATE);
  Display[] displays=((DisplayManager)getSystemService(DISPLAY_SERVICE)).getDisplays();
  if(getWindowManager().getDefaultDisplay().getDisplayId()==0 && !getIntent().getBooleanExtra("bottom",false)){
   for(Display d:displays)if(d.getDisplayId()!=0 && d.getName().equals("Screen-2")){
    try{Intent i=new Intent(this,MainActivity.class).putExtra("bottom",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK);ActivityOptions o=ActivityOptions.makeBasic();o.setLaunchDisplayId(d.getDisplayId());startActivity(i,o.toBundle());finish();return;}catch(Exception e){Toast.makeText(this,"Could not open bottom display: "+e.getMessage(),Toast.LENGTH_LONG).show();}
   }
  }
  getWindow().getDecorView().setSystemUiVisibility(5894);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
  FrameLayout root=new FrameLayout(this); ImageView bg=new ImageView(this);background=bg;bg.setBackgroundColor(0xff101923);bg.setScaleType(ImageView.ScaleType.CENTER_CROP);root.addView(bg,new FrameLayout.LayoutParams(-1,-1));
  shade=new View(this);shade.setBackgroundColor(0xcf080b10);root.addView(shade,new FrameLayout.LayoutParams(-1,-1));
  panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(24,12,24,12);root.addView(panel,new FrameLayout.LayoutParams(-1,-1));
  TextView title=text("HUNTER’S COMPANION",24);title.setTypeface(Typeface.SERIF,Typeface.BOLD);title.setTextColor(gold);panel.addView(title);
  TextView sub=text("UNOFFICIAL  ·  BRING YOUR OWN GAME",11);sub.setTextColor(gold);panel.addView(sub);
  folderStatus=text("Choose your extracted game folder to begin.",12);panel.addView(folderStatus);
  LinearLayout tabs=new LinearLayout(this);panel.addView(tabs);button(tabs,"Controls",()->show(false));button(tabs,"Artwork",()->show(true));button(tabs,"Setup",()->chooseFolder());button(tabs,"Help",()->help());
  ScrollView scroll=new ScrollView(this);body=text("",17);body.setPadding(0,10,0,8);scroll.addView(body);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  LinearLayout actions=new LinearLayout(this);panel.addView(actions);button(actions,"Open game ↗",()->launchGame());button(actions,"Back to launcher",()->finish());
  setContentView(root);show(false);String saved=prefs.getString("tree",null);prefs.edit().putBoolean("valid",false).apply();if(saved!=null)validate(Uri.parse(saved));
 }
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(ink);t.setLineSpacing(4,1);return t;}
 void button(LinearLayout row,String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextSize(12);b.setTextColor(ink);b.setAllCaps(false);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xb3242930));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,(int)(48*getResources().getDisplayMetrics().density),1);p.setMargins(2,5,2,5);row.addView(b,p);b.setOnClickListener(v->r.run());}
 void show(boolean a){art=a; shade.setBackgroundColor(a?0x40080b10:0xcf080b10); body.setText(a?"\n\n\n\n\nYour journey awaits.":"COMBAT\nR1  ·  Attack               R2  ·  Heavy / hold to charge\nL1  ·  Transform          L2  ·  Left-hand weapon\n\nFACE BUTTONS — BY POSITION\nTop  △  ·  Blood vial / heal\nRight  ○  ·  Dodge / hold to run\nBottom  ×  ·  Interact / confirm\nLeft  □  ·  Use selected item\n\nMOVEMENT\nLeft stick  ·  Move       Right stick  ·  Camera\nR3  ·  Lock on / center camera\nD-pad down  ·  Cycle quick items\nD-pad left / right  ·  Switch weapons");body.setTextSize(a?24:16);body.setGravity(a?Gravity.CENTER:Gravity.START);}
 void launchGame(){if(!prefs.getBoolean("valid",false)){chooseFolder();return;}try{Intent i=getPackageManager().getLaunchIntentForPackage("com.ducvd89.bloodborne");if(i==null)throw new Exception("Bloodborne is not installed");i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);ActivityOptions o=ActivityOptions.makeBasic();o.setLaunchDisplayId(0);startActivity(i,o.toBundle());}catch(Exception e){new AlertDialog.Builder(this).setMessage(e.getMessage()).setPositiveButton("OK",null).show();}}
 void chooseFolder(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,40);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=40||result!=RESULT_OK||data==null||data.getData()==null)return;Uri tree=data.getData();try{getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION);String previous=prefs.getString("tree",null);prefs.edit().putString("tree",tree.toString()).putBoolean("valid",false).apply();if(previous!=null&&!previous.equals(tree.toString()))try{getContentResolver().releasePersistableUriPermission(Uri.parse(previous),Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}validate(tree);}catch(Exception e){folderStatus.setText("Folder access failed. Choose it again in Setup.");}}
 Uri child(Uri tree,String parent,String name)throws Exception{Uri list=DocumentsContract.buildChildDocumentsUriUsingTree(tree,parent);try(Cursor c=getContentResolver().query(list,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(c!=null)while(c.moveToNext())if(name.equals(c.getString(1)))return DocumentsContract.buildDocumentUriUsingTree(tree,c.getString(0));}return null;}
 boolean validEntry(Uri uri,boolean directory)throws Exception{if(uri==null)return false;try(Cursor c=getContentResolver().query(uri,new String[]{DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE},null,null,null)){if(c==null||!c.moveToFirst())return false;boolean isDir=DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(0));return directory?isDir:!isDir&&!c.isNull(1)&&c.getLong(1)>0;}}
 void validate(Uri tree){folderStatus.setText("Checking selected folder…");new Thread(()->{String message;android.graphics.Bitmap bitmap=null;boolean valid=false;try{String id=DocumentsContract.getTreeDocumentId(tree);StringBuilder missing=new StringBuilder();for(String name:new String[]{"eboot.bin","dvdroot_ps4","sce_module","sce_sys"})if(!validEntry(child(tree,id,name),!name.equals("eboot.bin")))missing.append(name).append("  ");valid=missing.length()==0;if(!valid)message="Missing: "+missing+"— choose the folder containing eboot.bin.";else{message="Game folder selected · also select it in Bloodborne";Uri sys=child(tree,id,"sce_sys");Uri image=child(tree,DocumentsContract.getDocumentId(sys),"pic1.png");if(image!=null){BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;try(InputStream bounds=getContentResolver().openInputStream(image)){BitmapFactory.decodeStream(bounds,null,opts);}opts.inJustDecodeBounds=false;opts.inSampleSize=1;while(opts.outWidth/opts.inSampleSize>1600||opts.outHeight/opts.inSampleSize>1600)opts.inSampleSize*=2;try(InputStream in=getContentResolver().openInputStream(image)){bitmap=BitmapFactory.decodeStream(in,null,opts);}}}}catch(Exception e){message="Folder unavailable. Reconnect storage or choose it again in Setup.";}final String status=message;final boolean ok=valid;final android.graphics.Bitmap art=bitmap;runOnUiThread(()->{if(isDestroyed()||!tree.toString().equals(prefs.getString("tree",null)))return;prefs.edit().putBoolean("valid",ok).apply();folderStatus.setText(status);background.setImageBitmap(art);});},"folder-check").start();}
 void help(){new AlertDialog.Builder(this).setTitle("Your second screen").setMessage("Setup selects only the folder you choose. Checks verify folder structure, not ownership, complete integrity, game version or playability. Artwork stays on your device. Select the same folder separately inside Bloodborne; permissions cannot be shared between apps. No game or native code is included.\n\nOpen Hunter’s Companion to show this panel on the Thor’s lower screen. Open game brings Bloodborne to the upper screen.\n\nBack to launcher closes only this panel and reveals Cocoon; it does not quit or save the game. This version does not monitor other apps or automatically close when Bloodborne exits.\n\nFor the built-in live map: in Bloodborne, press Back → Hunter’s Atlas → enable map → second screen. The map downloads data on first use and replaces this panel.\n\nControls are a reference, not touch input. Face buttons use physical positions because the Thor’s printed letters differ from Xbox labels. No game files or saves are changed.").setPositiveButton("Got it",null).show();}
}
